export interface AccessibilityDevToolsOptions {
  // List of glob patterns to include in the linting process.
  include: string[];

  // List of glob patterns to exclude from the linting process.
  exclude?: string[];

  // BrowserStack credentials
  browserstackUsername: string;
  browserstackAccessKey: string;

  // Whether to run in non-strict mode, default: false
  nonStrict?: boolean;

  /**
   * Pre-resolved touched-lines map for --scope=diff. CLI binary constructs
   * this from git; library callers (JetBrains, browserstack-binary proxy)
   * may construct it themselves.
   *
   * The `| null` is load-bearing: null/undefined skip the filter entirely;
   * an empty Map runs the filter and produces an empty report (CI mode
   * against an empty <base>...HEAD diff).
   *
   * Canonicalization recipe library callers MUST use: each key is the
   * result of `fs.realpathSync.native(path.resolve(gitRoot, repoRelativePath))`.
   * The CLI sets `gitRoot` from `git rev-parse --show-toplevel` (or the
   * `--git-root` flag if supplied) and the repo-relative path from the
   * diff's `+++ b/<path>` header (after octal-unescape for non-ASCII
   * filenames). Non-canonical keys silently miss the lookup; consumers
   * building their own touchedLines map MUST use the same transform on
   * the same `gitRoot` or the file-level gate will exclude all their
   * files.
   *
   * NOT safely serializable across worker/RPC boundaries that lose
   * Map/Set semantics. In-process only.
   *
   * (See ADR-0022 Programmatic contract for the full design rationale.)
   */
  touchedLines?: TouchedLines | null;
}

/**
 * `--scope` CLI option. `'all'` lints every matched file (default);
 * `'diff'` restricts the report to files-and-lines touched by the current
 * git diff. See ADR-0022 / DEVA11Y-441.
 */
export type Scope = 'diff' | 'all';

/**
 * Pre-resolved touched-lines map keyed by absolute, canonical file path.
 * Values are sets of 1-based line numbers added or modified in the diff.
 * In-process only — not safely serializable across worker/RPC boundaries
 * that lose `Map`/`Set` semantics.
 */
export type TouchedLines = Map<string, Set<number>>;

/**
 * @since 0.0.x — added with `--scope=diff` (DEVA11Y-441). New members may be
 *   added in minor/patch releases to surface additional failure modes (e.g.
 *   git-worktree edge cases). Consumers that exhaustively `switch` on this
 *   enum should include a `default` branch and treat unknown values as a
 *   generic failure.
 */
export enum GitErrorType {
  NOT_A_REPO = 'NOT_A_REPO',
  NOT_A_GIT_WORKTREE = 'NOT_A_GIT_WORKTREE',
  GIT_NOT_FOUND = 'GIT_NOT_FOUND',
  SHALLOW_CLONE = 'SHALLOW_CLONE',
  INVALID_BASE_REF = 'INVALID_BASE_REF',
  NO_STAGED_CHANGES = 'NO_STAGED_CHANGES',
  NO_UNCOMMITTED_CHANGES = 'NO_UNCOMMITTED_CHANGES',
  GIT_DIFF_FAILED = 'GIT_DIFF_FAILED',
  GIT_DIFF_TOO_LARGE = 'GIT_DIFF_TOO_LARGE',
}

/**
 * Error thrown when a git invocation fails during `--scope=diff` resolution.
 * Use `instanceof GitError` to distinguish diff-scoping failures from other
 * `Error` instances. The `type` field (a {@link GitErrorType}) carries the
 * specific failure mode for switch-style branching; `argv` and `cwd` are
 * captured for diagnostics. Thrown by the resolver invoked inside `runCLI`
 * when the CLI is in CI-style entrypoints; library consumers that supply
 * `touchedLines` directly will never encounter this.
 */
export class GitError extends Error {
  readonly type: GitErrorType;
  readonly argv: readonly string[];
  readonly cwd?: string;
  constructor(type: GitErrorType, message: string, argv: readonly string[], cwd?: string);
}

enum RunStatus {
  SUCCESS = 0,
  FAILURE = 1,
  ERROR = 2,
  /** Cumulative Fair-Usage wait exceeded `--fup-max-wait` (DEVA11Y-403). */
  FUP_EXHAUSTED = 3,
  /** RBAC denied the action for this account's role (ADR-0025, DEVA11Y-518). */
  PERMISSION_DENIED = 4,
}

export const EXIT_CODES = {
  SUCCESS: RunStatus.SUCCESS,
  FAILURE: RunStatus.FAILURE,
  ERROR: RunStatus.ERROR,
  FUP_EXHAUSTED: RunStatus.FUP_EXHAUSTED,
  PERMISSION_DENIED: RunStatus.PERMISSION_DENIED,
};

/**
 * Result of a programmatic lint run.
 *
 * `report` is populated when linting completed (even if zero violations were
 * found — consumers get an empty `LintReport` envelope rather than `null`).
 * `report` is `null` only on early exits: auth failure, no files matched the
 * include/exclude patterns, unsupported extensions, or lint dispatch error.
 * In those cases the relevant error message has been written to stderr.
 *
 * @since 1.0.0 — replaces the prior `Promise<RunStatus>` return type.
 *   Migration: `const code = await runA11yDevtools(opts)` becomes
 *   `const { exitCode, report } = await runA11yDevtools(opts)`.
 */
/**
 * Authenticated user's profile as surfaced by the linter-server
 * `get-user-profile` WebSocket response. Consumed by the `--format html`
 * renderer for the report header. Additive — older servers omit `name` and
 * consumers must degrade gracefully. PII — never log or emit to telemetry.
 * (Mirrors `UserProfile` in `a11y-common/types/websocket`.)
 */
export interface UserProfile {
  id: string;
  name?: string;
}

/**
 * Per-file source cache produced during the lint pass. Consumed by the
 * `--format html` `code_context` enrichment so the renderer never re-reads
 * files (avoids a race with edits between lint and render, and drops a
 * redundant fs op). Keyed by the same cwd-relative path used in
 * `LintReport.data[].file_path`. In-process only.
 */
export type SourceByFilePath = Map<string, string>;

export interface LintResult {
  exitCode: RunStatus;
  report: LintReport | null;
  /**
   * Authenticated user's profile. Populated when auth succeeded (may still
   * be null on early-exit paths). Consumed by `--format html` for
   * `run_metadata.profile`. Added in 1.2.0 (DEVA11Y-628).
   */
  userProfile?: UserProfile | null;
  /**
   * Cache of per-file source strings collected during linting. Threaded
   * through so `runCLI` can pass it to the html enrichment step without
   * re-reading files from disk. Added in 1.2.0 (DEVA11Y-628).
   */
  sourceByFilePath?: SourceByFilePath;
}

export default function runA11yDevtools(options: AccessibilityDevToolsOptions): Promise<LintResult>;

/**
 * Parsed-CLI-argv shape produced by {@link parseArgs}. This is a superset of
 * {@link AccessibilityDevToolsOptions} that includes the CLI-only flags
 * (`format`, `scope`, `base`, `gitRoot`). Library callers should generally
 * construct {@link AccessibilityDevToolsOptions} directly rather than going
 * through `parseArgs`; this type is exported primarily for tooling
 * (browserstack-binary proxy) that needs to inspect a parsed argv before
 * invoking `main()`.
 */
export type CLIArguments = {
  include: string[];
  exclude?: string[];
  format?: OutputFormat;
  /**
   * Path to write formatted output to. Resolved default for `--format html`
   * is `accessibility-devtools-report.html`; text/xcode/json/sonar default
   * to stdout when omitted. Added with `--format html` (DEVA11Y-628, 1.2.0).
   */
  output?: string;
  browserstackUsername: string;
  browserstackAccessKey: string;
  nonStrict?: boolean;
  scope?: Scope;
  base?: string;
  gitRoot?: string;
  /**
   * Pre-resolved touched-lines map. Populated by the CLI-binary block in
   * `index.ts` from `resolveDiff()` before invoking `main()`; never set by
   * `parseArgs()` itself. Library callers (browserstack-binary proxy,
   * JetBrains plugin) may construct and pass this directly. See ADR-0022
   * R11 (CLI owns git; library entry point stays git-free).
   */
  touchedLines?: TouchedLines | null;
  /**
   * Client-side pacing (DEVA11Y-403): max lint requests per minute; `'0'` =
   * unlimited. String from commander; default `'480'`. Mirrors `src/cliArgs.ts`.
   */
  maxRequestsPerMin?: string;
  /**
   * Client-side pacing (DEVA11Y-403): max in-flight lint requests at once;
   * `'0'` = unlimited. String from commander; default `'25'`. Mirrors
   * `src/cliArgs.ts`.
   */
  maxConcurrency?: string;
  /**
   * CI/PR-scan mode (DEVA11Y-463). Additive and inert unless `prScan` is true.
   * `repo`/`prNumber` are required when `prScan` is set; `headSha` defaults to
   * `git rev-parse HEAD`; `ciServiceUrl` targets the CI review service.
   */
  prScan?: boolean;
  repo?: string;
  prNumber?: number;
  headSha?: string;
  ciServiceUrl?: string;
  /**
   * Max cumulative wall-clock (seconds, as a string) the CLI will spend waiting
   * out Fair-Usage `fup_limit_exceeded` rejections before exiting FUP_EXHAUSTED.
   * Default `'600'`; `'0'` waits indefinitely. Honored by both interactive lint
   * and `--pr-scan` (DEVA11Y-403, ADR-0033).
   */
  fupMaxWait?: string;
};

/**
 * `--format` CLI option. Re-declared here so the public `CLIArguments` type
 * can reference it without importing from src/. Mirrors `OutputFormat` in
 * `src/cliArgs.ts`.
 */
/**
 * `--format` CLI option. Re-declared here so the public `CLIArguments` type
 * can reference it without importing from src/. Mirrors `OutputFormat` in
 * `src/formatters/index.ts`.
 *
 * `'html'` (DEVA11Y-628, 1.2.0) emits a self-contained downloadable
 * accessibility report to the path given by `--output` (default
 * `accessibility-devtools-report.html`). Additive — text/json/sonar/xcode
 * consumers are unaffected.
 */
export type OutputFormat = 'text' | 'json' | 'sonar' | 'xcode' | 'html';

// internal
/**
 * Parse argv into a {@link CLIArguments} structure, or return `null` on
 * argv-shape errors that the CLI binary handles by exiting non-zero. The
 * `null` return covers two distinct failure modes; both are accompanied by a
 * stderr message printed by `parseArgs` itself:
 *
 *   (a) Missing required `--include` flag.
 *   (b) `--base` supplied without `--scope=diff` (incompatible combination).
 *
 * The CLI binary's `if (!parsedArgs) process.exit(ERROR)` handles both
 * uniformly; library callers that need to distinguish these cases should
 * generally build {@link AccessibilityDevToolsOptions} directly and bypass
 * `parseArgs`.
 *
 * `args` defaults to `process.argv.slice(2)` when omitted.
 */
export function parseArgs(args?: string[]): null | CLIArguments;
export function main(options: AccessibilityDevToolsOptions): Promise<LintResult>;

// =====================================================================
// Public output schemas — `--format json` and `--format sonar`.
// =====================================================================

// ---- LintReport (`--format json`) ----------------------------------

export interface LintReport {
  /**
   * Semantic version of the schema. Bumps are RESERVED for breaking shape
   * changes (field removal, type change, semantics change of an existing
   * field — including required→optional widening for fields that downstream
   * consumers may dereference directly). Strictly additive fields — new
   * optional fields that consumers can safely ignore (e.g.
   * `files_with_touched_lines` added in 1.0) — do NOT bump.
   *
   * Bumped to `'1.1'` because `SourcePoint.line` and `SourcePoint.column`
   * were widened from required to optional: existing consumers that
   * dereference `.line` / `.column` directly will see `undefined` for
   * file-level violations (Android native Lint, plain HTML Spectra with no
   * line anchor) and must handle that case.
   *
   * Consumers should be tolerant of unknown fields rather than asserting
   * equality against a pinned version string.
   */
  schema_version: string;
  summary: ReportSummary;
  data: FileReport[];
}

export interface ReportSummary {
  files_scanned: number;
  files_with_issues: number;
  total_issues: number;
  /**
   * Number of files whose touched lines were considered during a
   * `--scope=diff` run AND that survived `--include`/`--exclude` filtering.
   * `0` when the report was produced without a touched-lines filter
   * (`--scope=all` or programmatic callers that did not pass `touchedLines`).
   * This counts files that ENTERED the line-level overlap check (i.e.
   * matched both the lint-target set and the touched map), NOT the raw diff
   * size. Additive field — `schema_version` is unchanged (see
   * `LintReport.schema_version` JSDoc).
   */
  files_with_touched_lines: number;
  count_by_severity: SeverityCount;
}

export interface SeverityCount {
  error: number;
  warn: number;
  info: number;
}

export interface FileReport {
  /** Path relative to the CLI's working directory. */
  file_path: string;
  count_by_severity: SeverityCount;
  /** Violations grouped by `rule_id`; per-instance occurrences live in `rule_issues`. */
  aggregated_results: RuleResult[];
}

export type Severity = 'error' | 'warn' | 'info';

export interface RuleResult {
  /**
   * Rule identifier with the framework segment stripped, e.g. `accessibility-label`,
   * `image-alt`, `img-redundant-alt`. The wire format is engine-prefixed
   * (`swift/accessibility-label`); the normalizer strips the leading `<framework>/`
   * segment so consumers can aggregate the same rule across instances regardless of
   * which engine produced it.
   */
  rule_id: string;
  /** Primary violation message. Always populated. */
  message: string;
  /**
   * Optional how-to-fix text. Present only when the rule engine emits a separate
   * suggestion (Swift, Android-Spectra, plain HTML Spectra). JSX and Android native
   * Lint do not provide one.
   */
  suggestion?: string;
  severity: Severity;
  rule_issues: RuleIssue[];
}

export interface RuleIssue {
  location: SourceLocation;
}

export interface SourceLocation {
  start: SourcePoint;
  /** Optional. Some engines (Android native Lint, plain HTML Spectra) don't always emit an end position. */
  end?: SourcePoint;
}

/**
 * 1-based source position. Both fields are optional: file-level violations
 * (e.g. Android native Lint flagging a manifest-wide issue, or plain HTML
 * Spectra surfacing a rule with no line anchor) omit both. Most engines
 * populate both; consumers should treat `undefined` as "no source anchor —
 * apply to the whole file."
 */
export interface SourcePoint {
  line?: number;
  column?: number;
}

// ---- SonarReport (`--format sonar`) --------------------------------

export interface SonarReport {
  rules: SonarRule[];
  issues: SonarIssue[];
}

export interface SonarRule {
  /** Matches `SonarIssue.ruleId`. Framework prefix stripped, like `LintReport.rule_id`. */
  id: string;
  name: string;
  description: string;
  engineId: 'browserstack-accessibility-devtools';
  /** Always `CODE_SMELL` for accessibility violations. */
  type: 'CODE_SMELL';
  severity: SonarLegacySeverity;
  cleanCodeAttribute?: SonarCleanCodeAttribute;
}

export type SonarLegacySeverity = 'BLOCKER' | 'CRITICAL' | 'MAJOR' | 'MINOR' | 'INFO';

/** SonarQube fixed enum; we currently emit `RESPECTFUL` uniformly. */
export type SonarCleanCodeAttribute =
  | 'FORMATTED'
  | 'CONVENTIONAL'
  | 'IDENTIFIABLE'
  | 'CLEAR'
  | 'LOGICAL'
  | 'COMPLETE'
  | 'EFFICIENT'
  | 'FOCUSED'
  | 'DISTINCT'
  | 'MODULAR'
  | 'TESTED'
  | 'LAWFUL'
  | 'TRUSTWORTHY'
  | 'RESPECTFUL';

export interface SonarIssue {
  /** References a `SonarRule.id`. Framework prefix stripped. */
  ruleId: string;
  primaryLocation: SonarLocation;
  effortMinutes?: number;
  secondaryLocations?: SonarLocation[];
}

export interface SonarLocation {
  message: string;
  filePath: string;
  textRange?: SonarTextRange;
}

export interface SonarTextRange {
  startLine: number;
  endLine?: number;
  startColumn?: number;
  endColumn?: number;
}
